erFrom( IERC20 token, address from, address to, uint256 value ) internal { _callOptionalReturn(token, abi.encodeWithSelector(token.transferFrom.selector, from, to, value)); } function safeApprove( IERC20 token, address spender, uint256 value ) internal { require( (value == 0) || (token.allowance(address(this), spender) == 0), "SafeERC20: approve from non-zero to non-zero allowance" ); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, value)); } function safeIncreaseAllowance( IERC20 token, address spender, uint256 value ) internal { uint256 newAllowance = token.allowance(address(this), spender) + value; _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, newAllowance)); } function safeDecreaseAllowance( IERC20 token, address spender, uint256 value ) internal { unchecked { uint256 oldAllowance = token.allowance(address(this), spender); require(oldAllowance >= value, "SafeERC20: decreased allowance below zero"); uint256 newAllowance = oldAllowance - value; _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, newAllowance)); } } function safePermit( IERC20Permit token, address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s ) internal { uint256 nonceBefore = token.nonces(owner); token.permit(owner, spender, value, deadline, v, r, s); uint256 nonceAfter = token.nonces(owner); require(nonceAfter == nonceBefore + 1, "SafeERC20: permit did not succeed"); } function _callOptionalReturn(IERC20 token, bytes memory data) private { bytes memory returndata = address(token).functionCall(data, "SafeERC20: low-level call failed"); if (returndata.length > 0) { require(abi.decode(returndata, (bool)), "SafeERC20: ERC20 operation did not succeed"); } } } interface ISwapPlusv1 { struct swapRouter { string platform; address tokenIn; address tokenOut; uint256 amountOutMin; uint256 meta; uint256 percent; } struct swapLine { swapRouter[] swaps; } struct swapBlock { swapLine[] lines; } function swap(address tokenIn, uint256 amount, address tokenOut, address recipient, swapBlock[] calldata swBlocks) external payable returns(uint256, uint256); } contract LiquidXv2Zap { using SafeERC20 for IERC20; address public router; address public factory; address public swapPlus; address public wrappedETH; address public rewarder; mapping (address => bool) public operators; address public operatorSetter; mapping (address => mapping(address => mapping(uint256 => uint256))) public balanceOf; struct swapPath { ISwapPlusv1.swapBlock[] path; } event Deposit(address account, address token0, address token1, uint256 basketId, uint256 amount); event Withdraw(address account, address token0, address token1, uint256 basketId, uint256 amount); receive() external payable { } constructor(address _router, address _swapPlus, address _rewarder, address _wrappedETH) { router = _router; factory = ILiquidXv2Router01(_router).factory(); swapPlus = _swapPlus; wrappedETH = _wrappedETH; rewarder = _rewarder; operatorSetter = msg.sender; } modifier onlyOpertaor() { require(operators[msg.sender], "LiquidXv2Zap: !operator"); _; } function deposit(address account, address token, address tokenM, swapPath calldata path, address token0, address token1, uint256[3] calldata amount, uint256 basketId) public payable returns(uint256) { address pair = ILiquidXv2Factory(factory).getPair(token0, token1); require(pair != address(0), "LiquidXv2Zap: no pair"); uint256[6] memory lvar; lvar[3] = msg.value; address inToken = token; if (token != address(0)) { lvar[3] = IERC20(token).balanceOf(address(this)); IERC20(token).safeTransferFrom(account, address(this), amount[0]); lvar[3] = IERC20(token).balanceOf(address(this)) - lvar[3]; } else { inToken = wrappedETH; IWETH(wrappedETH).deposit{value: lvar[3]}(); } if (path.path.length > 0) { _approveTokenIfNeeded(inToken, swapPlus, lvar[3]); (, lvar[3]) = ISwapPlusv1(swapPlus).swap(inToken, lvar[3], tokenM, address(this), path.path); in