oken0, address token1, uint256 amount0, uint256 amount1) internal { if (amount0 > 0) { IERC20(token0).safeTransfer(account, amount0); } if (amount1 > 0) { IERC20(token1).safeTransfer(account, amount1); } } function _calculateSwapAmount(uint256 reserve, uint256 inAmount) internal pure returns(uint256) { uint256 a1 = reserve * reserve * 1997 *1997; uint256 a2 = 4 * 997 * reserve * inAmount * 1000; return (_sqrt(a1+a2) - reserve * 1997) / (2 * 997); } function _sqrt(uint x) internal pure returns (uint y) { uint z = (x + 1) / 2; y = x; while (z < y) { y = z; z = (x / z + z) / 2; } } function _addBalance(address account, address pair, uint256 basketId, uint256 amount) internal { balanceOf[account][pair][basketId] += amount; } function withdrawToken(address token, address target, uint256 amount) public onlyOpertaor { if (token == address(0)) { (bool success, ) = payable(target).call{value: amount}(""); require(success, "LiquidXv2Zap: Failed withdraw"); } else { IERC20(token).safeTransfer(target, amount); } } function setRouterAndFactory(address _router) public { require(msg.sender == operatorSetter, 'LiquidXv2Zap: FORBIDDEN'); router = _router; factory = ILiquidXv2Router01(_router).factory(); } function setSwapPlus(address _swapPlus) public { require(msg.sender == operatorSetter, 'LiquidXv2Zap: FORBIDDEN'); swapPlus = _swapPlus; } function setRewarder(address _rewarder) public { require(msg.sender == operatorSetter, 'LiquidXv2Zap: FORBIDDEN'); rewarder = _rewarder; } function setOperator(address _operator, bool mode) external { require(msg.sender == operatorSetter, 'LiquidXv2Zap: FORBIDDEN'); operators[_operator] = mode; } function setOperatorSetter(address _operatorSetter) external { require(msg.sender == operatorSetter, 'LiquidXv2Zap: FORBIDDEN'); operatorSetter = _operatorSetter; } function _approveTokenIfNeeded(address token, address spender, uint256 amount) private { uint256 oldAllowance = IERC20(token).allowance(address(this), spender); if (oldAllowance < amount) { if (oldAllowance > 0) { IERC20(token).safeApprove(spender, 0); } IERC20(token).safeApprove(spender, type(uint256).max); } } }

